const dni = $('Konfiguracja').first().json.dni;
const granica = Date.now() - dni * 86400000;
const wpisy = $input.all().map((i) => i.json)
  .filter((w) => Date.parse(w.isoDate || w.pubDate || 0) >= granica)
  .slice(0, 5)
  .map((w) => ({ tytul: w.title, link: w.link, zajawka: String(w.contentSnippet || '').slice(0, 280) }));
if (!wpisy.length) return []; // brak nowych wpisów – koniec bez newslettera
return [{ json: { wpisy, lista: wpisy.map((w) => '• ' + w.tytul + ' – ' + w.zajawka).join('\n') } }];

const SYSTEM = "Piszesz krótki, przyjazny wstęp do newslettera firmowego (2-3 zdania) i temat e-maila (maks. 60 znaków). Po polsku, bez clickbaitu i emoji. Opieraj się tylko na liście wpisów.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"temat\": temat e-maila, \"wstep\": 2-3 zdania}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Firma: ${$('Konfiguracja').first().json.nazwaFirmy}\nNowe wpisy:\n${$json.lista}`;
return {
  json: {
    ...$json,
    _aiPrompt: String(user).slice(0, 12000),
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (wstęp newslettera)').item.json };
delete ctx._aiPrompt;
let out = {};
let aiError = '';
try {
  const raw = $json.output ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"temat":"","wstep":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };

const esc = (s) => String(s || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = '<p>' + esc($json.wstep) + '</p>' + $json.wpisy.map((w) => '<h3><a href="' + esc(w.link) + '">' + esc(w.tytul) + '</a></h3><p>' + esc(w.zajawka) + '</p>').join('');
return { json: { ...$json, html } };
